using System;using System.Drawing;using System.Linq;using System.Windows.Forms;using DuelStructureSetup;
class GuiSmoke { [STAThread]static int Main(string[] args){Application.EnableVisualStyles();using(var f=new SetupForm()){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-30000,-30000);f.Show();Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,f.Size));image.Save(args[0]);}foreach(Control c in f.Controls)if(c.Right>f.ClientSize.Width||c.Bottom>f.ClientSize.Height)throw new Exception("Control outside client area: "+c.Text);if(!f.Controls.OfType<Button>().Any(b=>b.Text=="安装 / 更新")||!f.Controls.OfType<Button>().Any(b=>b.Text=="卸载编辑器")||!f.Controls.OfType<Button>().Any(b=>b.Text=="导出适配资料"))throw new Exception("Installer actions missing");}return 0;} }
